function remoteControlOwnershipNote(a,c){if(!a)return'';if(a.targetType==='moment'){const p=remoteControlFindMoment(a);if(!p)return'';if(p.authorId==='me')return'这条朋友圈由手机主人「'+S.me.name+'」发布，不是你发布的。';if(p.authorId===(c&&c.id))return'这条朋友圈就是你（'+(c.remark||c.name)+'本人）以前发布的，你必须明确知道是自己的内容，并用一句自然的话解释当时为什么发。';const x=getC(p.authorId);return'这条朋友圈由其他联系人「'+((x&&(x.remark||x.name))||'未知')+'」发布，不是你也不是'+S.me.name+'。';}if(a.targetType==='xPost'){const p=remoteControlFindTweet(a);if(!p)return'';if(p.who==='me')return'这条微博 / X由手机主人「'+S.me.name+'」发布，不是你发布的。';if(p.who===(c&&c.id)||p.name===(c&&(c.remark||c.name)))return'这条微博 / X就是你（'+(c.remark||c.name)+'本人）以前发布的，不能说成别人的；请用一句自然的话解释当时为什么发。';return'这条微博 / X由其他用户「'+(p.name||'未知')+'」发布，不是你也不是'+S.me.name+'。';}return'';}
function replaceChildrenCompat(el,node){if(!el)return;if(typeof el.replaceChildren==='function'){if(node==null)el.replaceChildren();else el.replaceChildren(node);return;}while(el.firstChild)el.removeChild(el.firstChild);if(node)el.appendChild(node);}
