  const ownership=remoteControlOwnershipNote(a,c),ownPost=/就是你（/.test(ownership),ctl=_remoteCtl,mustSpeak=!!(ctl&&!(ctl.roleSpokenCount>0)&&a&&a.op==='view'&&visibleFacts.length),cumulative=(ctl&&ctl.actions||[]).slice(-6).map(x=>String(x.memory||x.detail||'').slice(0,220)).filter(Boolean).join('\n');
  const note=task+'。\n【本次远控始终不变的目标与刚才微信上下文】\n'+remoteControlIntentContext(c)+'\n【当前页面真实归属】\n'+(ownership||'按下面内容里写明的人称和方向判断，不能把“手机主人”误当成你自己。')+'\n【当前页面实际显示】\n'+String(r.detail||'没有相关记录').slice(0,2400)+(cumulative?'\n【本轮此前已经看过，不能重复查看或忘记】\n'+cumulative:'')+'\n若这是聊天或私信详情，必须把上面连续的前后消息当作同一段上下文理解，不能只截取一句断章取义。若当前只是聊天或私信列表，列表里实际显示的名称和预览同样是你亲眼看到的真实内容，可以针对预览自然反应，但不能把预览之外的上下文当成已知事实。\n【发言要克制】你不是操作解说员，导航进度会由界面单独显示。禁止说“我先看看”“我正在看”“我去找一下”“找到了”“我现在打开”“我翻过去”或任何打开软件、翻页、执行命令的过程；只允许以真实的你对当前看到的具体内容作自然反应。'+(ownPost?'这是你自己发布的内容，必须针对这一条单独说一句简短自然的解释，不能说成别人发的。':mustSpeak?'本轮你还没有说过话，而当前屏幕已经有具体真实内容；你必须挑其中真正让你在意的一点，以自己的人设说一句自然反应，lines不能返回空数组。不要为了凑数概括页面。':'普通空页面或确实没有任何值得在意的内容可以安静；只要当前屏幕出现你在意、可疑、不舒服、想追问或想处理的具体内容，就以自己的口吻说1到2句短话。')+'你说的每个事实都必须逐字有当前页面内容支撑；不能编造屏幕上没有的内容，不能拿别处看过的内容冒充当前页面。不要说“系统/数据/快照/页面”，不要输出动作描写、序号或解释。'+deleteRule+'\n只输出JSON：{"lines":["角色说的第一句","可选第二句"],"delete":false,"messageIndex":-1}。';
