  if(app==='douyin'){if(a&&a.targetType==='dySearchHistory'){dyTab='search';remoteControlSetPage('dy');}else if(a&&a.targetType==='dyDmList'){dyTab='dm';remoteControlSetPage('dy');}else if(a&&(a.targetType==='dyDm'||a.op==='delete_douyin_dm')){dyTab='dm';if(a.targetId)remoteControlSetPage('dydm',{id:a.targetId});else remoteControlSetPage('dy');}else{const alreadyFeed=a&&(a.targetType==='dyHome'||a.targetType==='dyVideo')&&cur().p==='dy'&&dyTab==='feed';dyTab='feed';if(!alreadyFeed)remoteControlSetPage('dy');}return;}
