  for(let i=0;i<decisions.length;i++){if(!remoteControlActive()||ctl.cancelled)break;const a=decisions[i];await remoteControlOpenApp(a,c);if(!remoteControlActive()||ctl.cancelled)break;const visibleDelete=await remoteControlPrepareVisibleDelete(a);if(!remoteControlActive()||ctl.cancelled)break;const r=await remoteControlExecute(a,c);if(r.ok){ctl.actions.push({app:r.app,op:a.op,targetId:a.targetId||'',targetType:a.targetType||'',detail:r.detail,memory:r.memory,ts:Date.now()});save();}if(visibleDelete&&r.ok)await remoteControlShowVisibleDeleteResult(a);remoteControlScene(r,remoteControlStageCaption(a,r),i,decisions.length,visibleDelete?Object.assign({},a,{noNavigate:true}):a);await remoteControlShowRoleLines(await remoteControlRoleLines(c,a,r));}
