function remoteControlCompletionDetail(ctl,reason){const acts=(ctl&&Array.isArray(ctl.actions)?ctl.actions:[]).filter(a=>a&&a.ok!==false),seen=new Set(),facts=[];acts.forEach(a=>{const text=String(a.memory||a.detail||'').replace(/\s+/g,' ').trim();if(!text)return;const key=text.toLowerCase();if(seen.has(key))return;seen.add(key);facts.push(text.slice(0,520));});const stopped=!!(ctl&&ctl.cancelled),ending=String(reason||'远程操控已经结束').trim(),goal=String(ctl&&ctl.intentContext||'').trim();return '结束方式：'+ending+(stopped?'（是'+S.me.name+'亲手提前结束本次授权）':'')+'。'+(goal?'\n本次从微信里带进来的原始目标：'+goal.slice(-900):'')+'\n你本次亲手成功查看或执行的真实内容：\n'+(facts.length?facts.slice(0,16).map((x,i)=>(i+1)+'. '+x).join('\n'):'没有成功查看或执行任何项目。')+'\n身份必须分清：记录里的“手机主人”是'+S.me.name+'，不是你；标成“你本人”的电话、朋友圈或微博 / X才属于你。以上都是你本人刚刚做过、看到过的事实，你必须知道并记住，不能说成是'+S.me.name+'自己做的，也不能编造失败、未执行或记录外的操作。现在结合原始目标、结束方式、这些新事实和最近上下文自然发一轮微信；可以挑最在意的一两件回应，不必机械汇报全部，但绝不能装作不知道自己刚做了什么。刚才在远控过程中已经说过的话不要原句重发，已经回复过的旧聊天也不要再次回答。不要提系统、功能或远程操控。';}
