function wxLoginRecentIntent(cid){const c=getC(cid),rs=msgs(cid).filter(m=>m.role==='user'&&m.type!=='sys'&&!m._call).slice(-8).map(m=>({text:msgToText(m),time:+m.time||0})).filter(m=>m.text),text=rs.slice(-4).map(m=>m.text).join(' / ');
  const intro=/介绍一下自己|介绍自己|自我介绍|认识一下|打个招呼|说一下你是谁|你是谁/.test(text);
  const all=/每个人|所有人|每个|挨个|都发|全部/.test(text);
  const remarkRow=rs.slice().reverse().find(m=>m.time>+(c&&c._remarkAt||0)&&/(?:把|给|将|让|帮)?[^。！？!?\n]{0,12}(?:微信)?备注[^。！？!?\n]{0,12}(?:改|换|设|起)|(?:改|换|设|起)[^。！？!?\n]{0,12}(?:微信)?备注/.test(m.text)),remarkText=remarkRow&&remarkRow.text||'',remark=!!(remarkRow&&!/(?:不要|别|不用|无需|不必|不许|禁止|先不)[^。！？!?\n]{0,14}(?:改|换|设|起|备注)/.test(remarkText));
  return {text:text.slice(-300),intro,all,remark,remarkAt:remark?remarkRow.time:0};}
function wxLoginApplyRemarkResponse(c,raw,intent){if(!c||!S.wxLogin||S.wxLogin.by!==c.id||S.wxLogin.remarkApplied)return false;const text=String(raw||''),re=/[\[【]\s*改备注\s*[\|｜:：]\s*([^\]】\n]{1,16})[\]】]/g;let m;while((m=re.exec(text))){const nv=m[1].trim(),allowed=!!(intent&&intent.remark)||Date.now()-(c._remarkAt||0)>2.5*86400000;if(!allowed||!roleRemarkApply(c,nv))continue;S.wxLogin.remarkApplied=true;wxLoginRecordAction(c,'remark','自己','把备注改成「'+nv+'」');S.wxLogin.did=S.wxLogin.did||[];S.wxLogin.did.push('你把自己的备注改成了「'+nv+'」');return true;}return false;}
async function wxLoginEnsureRequestedRemark(c,cid,sessionId,intent,first){if(!intent||!intent.remark||!S.wxLogin||S.wxLogin.sessionId!==sessionId||S.wxLogin.remarkApplied)return false;let raw='';try{raw=await chatAPI([{role:'system',content:buildSystem(c)},{role:'assistant',content:String(first||'')},{role:'user',content:'[刚才'+S.me.name+'明确要求你改掉自己在ta微信里的备注，但上一版没有真正执行，或给出的备注无效。现在只输出一行 [改备注|新的备注名]。新名字必须由你本人结合姓名、人设、职业、口头禅、近期相处和关系阶段决定，1至16字，不能与当前备注相同，不能解释，也不能输出其他操作。]'}],{routeIndex:roleChatRouteIndex(c),aux:c.model==='aux',max:80});}catch(_){}if(!S.wxLogin||S.wxLogin.sessionId!==sessionId||S.wxLogin.by!==cid)return false;return wxLoginApplyRemarkResponse(c,raw,intent);}
function wxLoginPendingFriendRequests(cid){friendRequestsInit();return (S.friendRequests||[]).filter(r=>r&&r.status==='pending'&&friendRequestVisible(r)&&r.contactId!==cid).map(r=>{const c=getC(r.contactId);return c?{key:r.id,name:c.remark||c.name,source:r.source||'好友申请',intent:r.intent||'',message:friendReqText(r.msg,'想认识你，可以通过一下吗？'),time:factStamp(r.visibleAt||r.time||Date.now())}:null;}).filter(Boolean).sort((a,b)=>String(b.time).localeCompare(String(a.time))).slice(0,20);}
function wxLoginPendingFriendPrompt(cid){const rows=wxLoginPendingFriendRequests(cid);if(!rows.length)return'\n\n【好友 → 新的朋友】当前没有等待处理的好友申请，绝不能编造或声称拒绝了谁。';return'\n\n【好友 → 新的朋友｜当前真实等待处理的申请】\n'+JSON.stringify(rows)+'\n你已经登录微信，所以现在可以查看这些申请并按你自己的性格、关系、占有欲和申请内容决定是否拒绝。普通合理申请可以保留，一个都不拒绝也可以；不要机械全拒。要拒绝时每个申请单独一行使用 [拒绝新朋友|申请key或页面姓名]，可以原样填写key，也可以填写上面列表中的完整姓名；若要拒绝两个人就输出两行，不能把两个姓名塞在同一项里。只有真实执行成功的申请才算拒绝，执行失败时退出后绝不能声称已经拒绝。没有登录微信时绝对无法执行。';}
function wxLoginResolvePendingFriend(cid,ref){ref=String(ref||'').trim();if(!ref)return null;const rows=wxLoginPendingFriendRequests(cid),compact=ref.replace(/\s+/g,'');return rows.find(x=>x.key===ref)||rows.find(x=>String(x.name||'').trim()===ref)||rows.find(x=>String(x.name||'').replace(/\s+/g,'')===compact)||null;}
function wxLoginRejectPendingFriend(cid,ref){if(!wxLoginActive()||!S.wxLogin||S.wxLogin.by!==cid)return null;const row=wxLoginResolvePendingFriend(cid,ref);if(!row)return null;ignoreFriend(row.key);const req=(S.friendRequests||[]).find(x=>x.id===row.key);if(!req||req.status!=='rejected')return null;const c=getC(cid);if(c){req._wxlogin=true;req._wxloginBy=cid;req._wxloginByName=wxLoginSelfName(c);wxLoginRecordAction(c,'reject_request',row.name,'拒绝新朋友申请');S.wxLogin.did=Array.isArray(S.wxLogin.did)?S.wxLogin.did:[];S.wxLogin.did.push('你在微信“好友 → 新的朋友”里亲手拒绝了「'+row.name+'」的申请');}return row;}
function wxLoginFriendRejectRefs(raw,cid){const text=String(raw||''),refs=[],push=v=>{String(v||'').split(/[、,，/]|\s+和\s*|\s+及\s*/).map(x=>x.trim()).filter(Boolean).forEach(x=>{if(!refs.includes(x))refs.push(x);});},re=/[\[【]\s*(?:拒绝新朋友|拒绝好友申请|拒绝申请)\s*[\|｜:：]\s*([^\]】\n]+)[\]】]/g;let m;while((m=re.exec(text)))push(m[1]);if(!refs.length){splitBubbles(text).forEach(line=>{if(!/(?:拒绝|拒掉|不通过)/.test(line)||/(?:不拒绝|先不拒绝|不要拒绝|保留|不处理)/.test(line))return;wxLoginPendingFriendRequests(cid).forEach(row=>{if(line.includes(row.name))push(row.name);});});}return refs;}
function wxLoginSelfName(c){return ((c&&c.name)||'').trim()||((c&&c.selfcall)||'').trim()||((c&&c.remark)||'').trim()||'我';}
function wxLoginDisplayName(c){return (c&&c.remark)||wxLoginSelfName(c);}
function wxLoginRe(s){return String(s||'').replace(/[-/\\^$*+?.()|[\]{}]/g,'\\$&');}
function wxLoginFixSelfName(c,s){const real=wxLoginSelfName(c),rem=((c&&c.remark)||'').trim();if(!rem||!real||rem===real)return s;const rr=wxLoginRe(rem);return s.replace(new RegExp('((?:我是|我叫|这里是|本人是)\\s*)'+rr,'g'),'$1'+real).replace(new RegExp('自我介绍一下[，,、\\s]*我是\\s*'+rr,'g'),'自我介绍一下，我是'+real);}
function wxLoginIntroLine(c,type,targetName,seed){const nm=wxLoginSelfName(c),me=S.me.name||'我',p=((c&&c.persona)||'')+' '+((c&&c.signature)||''),t=(c&&c.traits)||{},own=+t.own||0,idx=Math.abs(String((targetName||type||'')+'|'+(seed||0)+'|'+nm).split('').reduce((a,x)=>((a*31+x.charCodeAt(0))|0),7));let pool;
  if(own>=68||/强势|占有|主导|dom|控制|霸道/i.test(p))pool=type==='pfg'?['借'+me+'的号留句话。我是'+nm+'，她身边有我，聊天都注意分寸。','先让各位认个名字，'+nm+'。我借'+me+'的号来看看，也顺便告诉你们她有人在意。']:['借'+me+'的号直接说一声，'+targetName+'，我是'+nm+'。她是我很在意的人，以后相处分寸一点。','先认识一下，'+targetName+'。名字是'+nm+'，我借'+me+'的号来看看你，也让你知道她身边有我。'];
  else if(/冷淡|理性|克制|寡言|高冷|严谨/.test(p))pool=type==='pfg'?['占用一句，'+nm+'。借'+me+'的号认一下人，不必特意寒暄。','留个名字：'+nm+'。我只是借'+me+'的号看过来，大家照常聊。']:[''+targetName+'，先留个名字，'+nm+'。我借'+me+'的号认一下人，不用客套。','我看过你们最近的聊天了。'+targetName+'，叫我'+nm+'就行。'];
  else if(/活泼|调皮|幽默|毒舌|嘴欠|爱逗|开朗/.test(p))pool=type==='pfg'?['突击冒个泡——'+nm+'。借'+me+'的号来认认她平时都和谁聊天。','借号巡场一下，我是'+nm+'。别紧张，我只是来混个脸熟。']:['抓到一个'+targetName+'。我是'+nm+'，借'+me+'的号来混个脸熟。','突击认识一下，'+targetName+'——'+nm+'。她的号暂时在我手里，顺路来看看你。'];
  else if(/温柔|体贴|礼貌|沉稳|成熟/.test(p))pool=type==='pfg'?['打扰一下，我叫'+nm+'。常听'+me+'提到身边的人，今天借她的号来认识大家。','借'+me+'的号和大家留个招呼，我是'+nm+'。以后她还要麻烦各位照顾。']:[''+targetName+'，冒昧借'+me+'的号来认识一下。我叫'+nm+'，常听她提起身边的朋友。','一直没正式认识，今天借'+me+'的号补上。我是'+nm+'，很高兴知道她身边有你这个朋友。'];
  else pool=type==='pfg'?['借'+me+'的号来认一下人，我是'+nm+'。大家照常聊，不用拘束。','先留个名字，'+nm+'。今天借'+me+'的号路过，顺便和大家认识一下。']:[''+targetName+'，借'+me+'的号来认个脸。我是'+nm+'，以后碰见就不算陌生了。','先不走固定客套话了——我叫'+nm+'。借'+me+'的号来看看，也顺便认识你。'];
  return pool[idx%pool.length];}
function wxLoginBoundaryLine(c,type,targetName,seed){const p=((c&&c.persona)||'')+' '+((c&&c.signature)||''),own=+(((c&&c.traits)||{}).own)||0,key=Math.abs(String((targetName||type||'')+'|'+(seed||0)+'|'+wxLoginSelfName(c)).split('').reduce((a,x)=>((a*33+x.charCodeAt(0))|0),11));let pool;if(own>=68||/强势|占有|主导|dom|控制|霸道/i.test(p))pool=type==='pfg'?['大家正常聊天可以，越界的话自己掂量——她身边有我。','她愿意留在这个群是信任各位，谁把分寸弄丢了，我会亲自来问。']:[targetName+'，你和她正常来往我不拦，但暧昧和越界到此为止。','我看过你们的聊天了，'+targetName+'。该有的距离留好，别等我第二次提醒。'];else if(/冷淡|理性|克制|寡言|高冷|严谨/.test(p))pool=type==='pfg'?['正常交流即可，私密话题请各自把握边界。','群聊不需要因为我改变，只把不该公开或越界的内容收好。']:[targetName+'，正常联系没问题，边界请你自己把握。','我不干涉你们正常聊天，'+targetName+'，但分寸应该不用我解释。'];else if(/活泼|调皮|幽默|毒舌|嘴欠|爱逗|开朗/.test(p))pool=type==='pfg'?['聊天随意，挖墙脚免谈，我会看见。','路过查个岗，各位继续——只要没人打她的歪主意。']:[targetName+'，聊天欢迎，暧昧免谈——这句就当我提前打过招呼。','别紧张，'+targetName+'，我只是来看看谁胆子大到敢和她聊过界。'];else if(/温柔|体贴|礼貌|沉稳|成熟/.test(p))pool=type==='pfg'?['我尊重大家和她的来往，也希望太私人的话彼此留点分寸。','她很珍惜身边的人，我也一样；大家舒服相处，边界照顾好就行。']:[targetName+'，我尊重你们的来往，也希望你照顾好彼此的分寸。','她把你当朋友，我会尊重。只是太私人的话，麻烦你替她多想一点。'];else pool=type==='pfg'?['大家照常聊就好，太私人的话稍微注意一下。','借她的号看一眼，群里保持现在这样就好，别聊过线。']:[targetName+'，正常聊天没关系，只是别把界线聊没了。','我不拦你们联系，'+targetName+'，该有的分寸留着就行。'];return pool[key%pool.length];}
function wxLoginLooksPrivateTalk(s){s=(''+s).trim();return /^(baby|宝贝|宝宝|亲爱的|老婆|老公)[，,、\s]/i.test(s)||/这个群里发消息记得分寸|发消息记得分寸|有些话不该让外人看到|不该让外人看到|别让外人看到/.test(s);}
function wxLoginFixOutgoing(c,type,targetName,say,intent){let s=(''+(say||'')).replace(/\s+/g,' ').trim().slice(0,240);if(!s)return '';
  s=wxLoginFixSelfName(c,s);
  if(intent&&intent.intro&&!/(我是|我叫|这里是|名字|叫我|认识|留个|借.{0,8}号)/.test(s))s=wxLoginIntroLine(c,type,targetName,0);
  if(wxLoginLooksPrivateTalk(s)){
    if(intent&&intent.intro)return wxLoginIntroLine(c,type,targetName,1);
    return wxLoginBoundaryLine(c,type,targetName,((S.wxLogin&&S.wxLogin.actions)||[]).length);
  }
  if(S.wxLogin){const old=(c.wxLoginHistory||[]).reduce((z,h)=>z.concat(h.actions||[]),[]),used=(S.wxLogin.actions||[]).filter(a=>a.type==='send').concat(old.filter(a=>a.type==='send')).map(a=>a.text||'');if(used.some(x=>replyBigramScore(x,s)>=.82))s=(intent&&intent.intro)?wxLoginIntroLine(c,type,targetName,used.length+2):wxLoginBoundaryLine(c,type,targetName,used.length+2);}
  return s;}
